  1→import { useState } from "react";
  2→import { Badge } from "@/components/ui/badge";
  3→import { Button } from "@/components/ui/button";
  4→import { Separator } from "@/components/ui/separator";
  5→import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
  6→import { ScrollArea } from "@/components/ui/scroll-area";
  7→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
  8→import { Phone, Mail, FileText, Archive, MapPin, Download } from "lucide-react";
  9→import { toast } from "sonner";
 10→import type { Result } from "@/pages/Index";
 11→import type { HiringStage } from "@/hooks/useStageTracker";
 12→
 13→import CandidateSummary from "@/components/candidate/CandidateSummary";
 14→import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
 15→import ExperiencePanel from "@/components/candidate/ExperiencePanel";
 16→import EducationPanel from "@/components/candidate/EducationPanel";
 17→import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
 18→import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
 19→import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
 20→import StageTracker from "@/components/candidate/StageTracker";
 21→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
 22→
 23→interface CandidateDetailSheetProps {
 24→  result: Result | null;
 25→  isOpen: boolean;
 26→  onClose: () => void;
 27→  jobId?: string | null;
 28→  jobTitle?: string | null;
 29→  formatCandidateName: (filename: string) => string;
 30→  onDownload: (filePath: string, filename: string) => void;
 31→  onDismiss: (resumeId: string) => void;
 32→  currentStage?: HiringStage | null;
 33→  stageUpdatedAt?: string | null;
 34→  onStageChange?: (resumeId: string, stage: HiringStage) => void;
 35→}
 36→
 37→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 38→  if (score >= 70) return { label: "Strong", variant: "success" };
 39→  if (score >= 40) return { label: "Good", variant: "warning" };
 40→  return { label: "Weak", variant: "destructive" };
 41→};
 42→
 43→const CandidateDetailSheet = ({
 44→  result: r,
 45→  isOpen,
 46→  onClose,
 47→  jobId,
 48→  jobTitle,
 49→  formatCandidateName,
 50→  onDownload,
 51→  onDismiss,
 52→  currentStage,
 53→  stageUpdatedAt,
 54→  onStageChange,
 55→}: CandidateDetailSheetProps) => {
 56→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
 57→
 58→  if (!r) return null;
 59→
 60→  const strength = getStrengthLabel(r.overall_score);
 61→  const candidateName = r.candidate_name || formatCandidateName(r.filename);
 62→
 63→  return (
 64→    <>
 65→      <Sheet open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
 66→        <SheetContent side="right" className="sm:max-w-2xl w-full p-0 flex flex-col gap-0">
 67→          {/* Header */}
 68→          <SheetHeader className="px-6 pt-6 pb-0 shrink-0 space-y-0">
 69→            <div className="flex items-start justify-between gap-4 pr-6">
 70→              <div className="min-w-0">
 71→                <SheetTitle className="text-lg truncate">{candidateName}</SheetTitle>
 72→                {(r.candidate_location || r.candidate_email) && (
 73→                  <div className="flex items-center gap-2 mt-1 flex-wrap">
 74→                    {r.candidate_location && (
 75→                      <span className="flex items-center gap-1 text-xs text-muted-foreground">
 76→                        <MapPin className="h-3 w-3" /> {r.candidate_location}
 77→                      </span>
 78→                    )}
 79→                    {r.candidate_email && (
 80→                      <span className="text-xs text-muted-foreground">{r.candidate_email}</span>
 81→                    )}
 82→                  </div>
 83→                )}
 84→              </div>
 85→            </div>
 86→          </SheetHeader>
 87→
 88→          {/* Score bar + actions */}
 89→          <div className="px-6 py-3 flex items-center gap-3 flex-wrap shrink-0">
 90→            <div className="flex items-center gap-2.5">
 91→              <span className="text-2xl font-semibold tabular-nums text-foreground">{r.overall_score?.toFixed(0)}%</span>
 92→              <Badge variant={strength.variant}>{strength.label}</Badge>
 93→              {r.scoring_version === "heuristic" && <Badge variant="secondary">Quick</Badge>}
 94→            </div>
 95→
 96→            <Separator orientation="vertical" className="h-5 hidden sm:block" />
 97→
 98→            <TooltipProvider delayDuration={300}>
 99→              <div className="flex items-center gap-0.5">
100→                {r.candidate_phone && (
101→                  <Tooltip>
102→                    <TooltipTrigger asChild>
103→                      <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
104→                        onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
105→                        <Phone className="h-3 w-3" /> Call
106→                      </Button>
107→                    </TooltipTrigger>
108→                    <TooltipContent>{r.candidate_phone}</TooltipContent>
109→                  </Tooltip>
110→                )}
111→                {r.candidate_email && (
112→                  <Tooltip>
113→                    <TooltipTrigger asChild>
114→                      <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
115→                        onClick={() => setEmailDialogOpen(true)}>
116→                        <Mail className="h-3 w-3" /> Email
117→                      </Button>
118→                    </TooltipTrigger>
119→                    <TooltipContent>Send email</TooltipContent>
120→                  </Tooltip>
121→                )}
122→                {r.file_path && (
123→                  <Tooltip>
124→                    <TooltipTrigger asChild>
125→                      <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
126→                        onClick={() => onDownload(r.file_path!, r.filename)}>
127→                        <Download className="h-3 w-3" /> Resume
128→                      </Button>
129→                    </TooltipTrigger>
130→                    <TooltipContent>Download resume</TooltipContent>
131→                  </Tooltip>
132→                )}
133→                <Tooltip>
134→                  <TooltipTrigger asChild>
135→                    <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-destructive"
136→                      onClick={() => { onDismiss(r.resume_id); onClose(); }}>
137→                      <Archive className="h-3.5 w-3.5" />
138→                    </Button>
139→                  </TooltipTrigger>
140→                  <TooltipContent>Archive</TooltipContent>
141→                </Tooltip>
142→              </div>
143→            </TooltipProvider>
144→          </div>
145→
146→          <Separator />
147→
148→          {/* Scrollable panels */}
149→          <ScrollArea className="flex-1">
150→            <div className="px-6 py-5 space-y-5">
151→              <CandidateSummary result={r} />
152→
153→              {onStageChange && (
154→                <StageTracker
155→                  currentStage={currentStage || "applied"}
156→                  updatedAt={stageUpdatedAt}
157→                  onStageChange={(stage) => onStageChange(r.resume_id, stage)}
158→                />
159→              )}
160→
161→              <StrengthsGapsPanel result={r} />
162→
163→              <div className="space-y-4">
164→                <SkillsDetailPanel result={r} />
165→                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
166→                  <ExperiencePanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves as string[]} />
167→                  <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} missingMustHaves={r.missing_must_haves} />
168→                </div>
169→              </div>
170→
171→              <JDAlignedPanel result={r} />
172→
173→              <InterviewQuestionsPanel result={r} />
174→            </div>
175→          </ScrollArea>
176→        </SheetContent>
177→      </Sheet>
178→
179→      {r.candidate_email && (
180→        <EmailOutreachDialog
181→          open={emailDialogOpen}
182→          onOpenChange={setEmailDialogOpen}
183→          candidateName={candidateName}
184→          candidateEmail={r.candidate_email}
185→          jobTitle={jobTitle || "Open Position"}
186→          matchScore={Math.round(r.overall_score ?? 0)}
187→          resumeId={r.resume_id}
188→          jobId={jobId || ""}
189→        />
190→      )}
191→    </>
192→  );
193→};
194→
195→export default CandidateDetailSheet;
