 14→const getSkillLevel = (score: number): SkillLevel => {
 15→  if (score >= 90) return "Expert";
 16→  if (score >= 70) return "Adv";
 17→  if (score >= 55) return "Good";
 18→  if (score >= 40) return "Mid";
 19→  if (score >= 20) return "Low";
